:root {
  --bg: #1a1a2e;
  --card-bg: #16213e;
  --accent: #e94560;
  --accent-hover: #ff6b81;
  --text: #eaeaea;
  --muted: #a0a0b0;
  --border: #0f3460;
  --focus: #f5c542;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: 'Courier New', Courier, monospace;
  font-size: 18px;
  padding: 16px;
  color: var(--text);
}

.card {
  background: var(--card-bg);
  border: 4px solid var(--border);
  box-shadow: 8px 8px 0 var(--border);
  padding: 32px 24px;
  width: 100%;
  max-width: 420px;
  text-align: center;
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.title {
  font-size: 20px;
  letter-spacing: 2px;
  color: var(--accent);
  text-transform: uppercase;
}

.mode {
  font-size: 18px;
  letter-spacing: 3px;
  color: var(--muted);
  text-transform: uppercase;
}

.timer {
  font-size: clamp(48px, 18vw, 96px);
  font-weight: bold;
  letter-spacing: 4px;
  line-height: 1;
  color: var(--text);
  font-variant-numeric: tabular-nums;
}

.controls {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}

.btn {
  font-family: inherit;
  font-size: 18px;
  font-weight: bold;
  letter-spacing: 1px;
  padding: 14px 24px;
  min-width: 120px;
  min-height: 48px;
  background: var(--accent);
  color: var(--bg);
  border: 3px solid var(--accent);
  cursor: pointer;
  transition: background 0.1s, transform 0.05s, box-shadow 0.05s;
  box-shadow: 4px 4px 0 var(--border);
}

.btn:hover {
  background: var(--accent-hover);
  border-color: var(--accent-hover);
}

.btn:focus-visible {
  outline: 4px solid var(--focus);
  outline-offset: 2px;
}

.btn:active {
  transform: translate(4px, 4px);
  box-shadow: none;
}

.mode-switch {
  display: flex;
  gap: 12px;
  justify-content: center;
}

.mode-btn {
  font-family: inherit;
  font-size: 16px;
  letter-spacing: 1px;
  padding: 10px 16px;
  min-height: 44px;
  background: transparent;
  color: var(--muted);
  border: 2px solid var(--border);
  cursor: pointer;
  transition: background 0.1s, color 0.1s;
}

.mode-btn:hover {
  color: var(--text);
  border-color: var(--muted);
}

.mode-btn:focus-visible {
  outline: 4px solid var(--focus);
  outline-offset: 2px;
}

.mode-btn:active {
  transform: translate(2px, 2px);
}

.mode-btn.active {
  background: var(--border);
  color: var(--text);
  border-color: var(--accent);
}

@media (max-width: 400px) {
  .card {
    padding: 24px 16px;
  }
  .btn {
    min-width: 100px;
    padding: 12px 16px;
    font-size: 16px;
  }
  .mode-btn {
    padding: 8px 12px;
    font-size: 14px;
  }
}

const WORK_TIME = 25 * 60;
const BREAK_TIME = 5 * 60;

const timerDisplay = document.getElementById('timer-display');
const modeIndicator = document.getElementById('mode-indicator');
const startPauseBtn = document.getElementById('start-pause-btn');
const startPauseText = document.getElementById('start-pause-text');
const resetBtn = document.getElementById('reset-btn');
const workModeBtn = document.getElementById('work-mode-btn');
const breakModeBtn = document.getElementById('break-mode-btn');

let currentMode = 'work';
let totalSeconds = WORK_TIME;
let remainingSeconds = WORK_TIME;
let timerId = null;
let endTime = null;
let isRunning = false;

function formatTime(seconds) {
  const m = Math.floor(seconds / 60);
  const s = seconds % 60;
  return `${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`;
}

function updateDisplay() {
  timerDisplay.textContent = formatTime(remainingSeconds);
}

function setMode(mode) {
  currentMode = mode;
  stopTimer();
  if (mode === 'work') {
    totalSeconds = WORK_TIME;
    modeIndicator.textContent = 'WORK';
    workModeBtn.classList.add('active');
    workModeBtn.setAttribute('aria-pressed', 'true');
    breakModeBtn.classList.remove('active');
    breakModeBtn.setAttribute('aria-pressed', 'false');
  } else {
    totalSeconds = BREAK_TIME;
    modeIndicator.textContent = 'BREAK';
    breakModeBtn.classList.add('active');
    breakModeBtn.setAttribute('aria-pressed', 'true');
    workModeBtn.classList.remove('active');
    workModeBtn.setAttribute('aria-pressed', 'false');
  }
  remainingSeconds = totalSeconds;
  updateDisplay();
  startPauseText.textContent = 'START';
  startPauseBtn.setAttribute('aria-label', 'Start timer');
}

function tick() {
  const now = Date.now();
  const diff = Math.max(0, Math.round((endTime - now) / 1000));
  remainingSeconds = diff;
  updateDisplay();
  if (remainingSeconds <= 0) {
    stopTimer();
    startPauseText.textContent = 'START';
    startPauseBtn.setAttribute('aria-label', 'Start timer');
  }
}

function startTimer() {
  if (isRunning) return;
  isRunning = true;
  endTime = Date.now() + remainingSeconds * 1000;
  timerId = setInterval(tick, 200);
  startPauseText.textContent = 'PAUSE';
  startPauseBtn.setAttribute('aria-label', 'Pause timer');
}

function stopTimer() {
  if (timerId !== null) {
    clearInterval(timerId);
    timerId = null;
  }
  isRunning = false;
}

function toggleTimer() {
  if (isRunning) {
    stopTimer();
    startPauseText.textContent = 'START';
    startPauseBtn.setAttribute('aria-label', 'Start timer');
  } else {
    if (remainingSeconds <= 0) return;
    startTimer();
  }
}

function resetTimer() {
  stopTimer();
  remainingSeconds = totalSeconds;
  updateDisplay();
  startPauseText.textContent = 'START';
  startPauseBtn.setAttribute('aria-label', 'Start timer');
}

startPauseBtn.addEventListener('click', toggleTimer);
resetBtn.addEventListener('click', resetTimer);
workModeBtn.addEventListener('click', () => setMode('work'));
breakModeBtn.addEventListener('click', () => setMode('break'));

setMode('work');
